param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks",[string]$ModelRepo="D:\Dev\LotSizingDataModel")
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop"
function Step{param([string]$m) Write-Host "";Write-Host ("==> "+$m)}
function Ensure-Directory{param([string]$p) if(-not(Test-Path -LiteralPath $p -PathType Container)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
function NormCode{param([string]$v) if([string]::IsNullOrWhiteSpace($v)){return ""};$x=[regex]::Replace($v.ToUpperInvariant(),"[^A-Z0-9]","");if($x -match "([GK])([05])([0-4])([12])([1-5])([234])([012])"){return $Matches[1]+$Matches[2]+$Matches[3]+$Matches[4]+$Matches[5]+$Matches[6]+$Matches[7]};return ""}
function WbClass{param([string]$w)$n=[IO.Path]::GetFileNameWithoutExtension($w).ToLowerInvariant();switch -Regex($n){"^solutionsap$"{return "A+"};"^solutionsbp$"{return "B+"};"^solutionscm$"{return "LEGACY-CM"};"^solutionscp$"{return "C+"};"^solutionsc$"{return "C"};"^solutionsdp$"{return "D+"};"^solutionsd$"{return "D"};"^solutionsep$"{return "E+"};"^solutionse$"{return "E"};default{return "UNKNOWN"}}}
$stadt=Join-Path $BenchmarkRepo "benchmarks\STADTLER2003";$clspl=Join-Path $BenchmarkRepo "benchmarks\SUERIE_CLSPL";$rep=Join-Path $BenchmarkRepo "reports\v0.4.1";$meta=Join-Path $stadt "metadata";$lit=Join-Path $stadt "literature";$fpdir=Join-Path $rep "fingerprints";Ensure-Directory $rep;Ensure-Directory $meta;Ensure-Directory $fpdir
Step "Validating existing 2100-instance Stadtler corpus"
$exp=@(@{C="A+";F="Aplus";N=240},@{C="B+";F="Bplus";N=600},@{C="C";F="C";N=360},@{C="C+";F="Cplus";N=240},@{C="D";F="D";N=360},@{C="D+";F="Dplus";N=240},@{C="E";F="E";N=30},@{C="E+";F="Eplus";N=30})
$val=New-Object System.Collections.Generic.List[object];$total=0
foreach($s in $exp){$ir=Join-Path $stadt ($s.F+"\instances");$sum=Join-Path $stadt ($s.F+"\checker-reports\campaign-summary.txt");$n=@(Get-ChildItem -LiteralPath $ir -Filter "*.xml" -File -ErrorAction SilentlyContinue).Count;$ok=$false;$evidence="NONE";if(Test-Path -LiteralPath $sum){$bytes=[IO.File]::ReadAllBytes($sum);$t="";try{$u=New-Object System.Text.UTF8Encoding($false,$true);$t=$u.GetString($bytes)}catch{$t=[Text.Encoding]::Default.GetString($bytes)};$t=$t.Replace([char]0xFEFF,"").Replace([char]0x00A0," ");if($t -match "(?im)^[ \t]*Overall[ \t]*:[ \t]*VALID[ \t]*\r?$"){$ok=$true;$evidence="SUMMARY_OVERALL_VALID"}else{$ef=$null;$lf=$null;$li=$null;if($t -match "(?im)^[ \t]*Execution failures[ \t]*:[ \t]*(\d+)[ \t]*\r?$"){$ef=[int]$Matches[1]};if($t -match "(?im)^[ \t]*File load failures[ \t]*:[ \t]*(\d+)[ \t]*\r?$"){$lf=[int]$Matches[1]};if($t -match "(?im)^[ \t]*Loaded instances[ \t]*:[ \t]*(\d+)[ \t]*\r?$"){$li=[int]$Matches[1]};if($null-ne$ef -and $null-ne$lf -and $null-ne$li -and $ef-eq0 -and $lf-eq0 -and $li-eq$n){$ok=$true;$evidence="SUMMARY_COUNTS_VALID"}}};if(-not $ok){$manifest=Join-Path $stadt ($s.F+"\checker-reports\campaign-items.tsv");if(Test-Path -LiteralPath $manifest){$ml=@(Get-Content -LiteralPath $manifest -ErrorAction SilentlyContinue);$bad=@($ml|Where-Object{$_ -match "(?i)(LOAD_FAILED|EXECUTION_FAILED|ERROR|EXCEPTION)"});if($bad.Count-eq0 -and $n-gt0){$ok=$true;$evidence="MANIFEST_NO_FAILURE_MARKERS"}}};Write-Host ($s.C+": XML="+$n+"/"+$s.N+" checker="+$ok+" evidence="+$evidence);if($n-ne$s.N -or -not $ok){throw("Corpus validation failed for "+$s.C)};$total+=$n;$val.Add([pscustomobject]@{test_set=$s.C;expected=$s.N;actual=$n;checker_valid=$ok;checker_evidence=$evidence})}
if($total-ne2100){throw("Expected 2100 XML, found "+$total)};$val.ToArray()|Export-Csv (Join-Path $rep "stadtler-existing-corpus-validation.csv") -NoTypeInformation -Encoding UTF8;Write-Host "Existing corpus validated: 2100 / 2100. No XML will be regenerated."
Step "Building batch fingerprint tool";$proj=Join-Path $BenchmarkRepo "tools\StadtlerBatchFingerprint\StadtlerBatchFingerprint.csproj";& dotnet build $proj -c Release --nologo -p:ModelRepo=$ModelRepo;if($LASTEXITCODE-ne0){throw "Batch fingerprint build failed"}
Step "Batch fingerprinting STADTLER2003";$sfp=Join-Path $fpdir "stadtler-fingerprints.csv";& dotnet run --project $proj -c Release --no-build -p:ModelRepo=$ModelRepo -- "STADTLER2003" $stadt $sfp;if($LASTEXITCODE-ne0){throw "Stadtler fingerprint failed"}
Step "Batch fingerprinting SUERIE_CLSPL";$cfp=Join-Path $fpdir "clspl-fingerprints.csv";& dotnet run --project $proj -c Release --no-build -p:ModelRepo=$ModelRepo -- "SUERIE_CLSPL" $clspl $cfp;if($LASTEXITCODE-ne0){throw "CLSPL fingerprint failed"}
$sr=@(Import-Csv $sfp);$cr=@(Import-Csv $cfp);Write-Host ("Stadtler fingerprints: "+$sr.Count);Write-Host ("CLSPL canonical fingerprints: "+$cr.Count)
Step "Computing exact cross-family genealogy";$idx=@{};foreach($r in $cr){if(-not $idx.ContainsKey($r.fingerprint)){$idx[$r.fingerprint]=New-Object System.Collections.Generic.List[object]};$idx[$r.fingerprint].Add($r)};$cross=New-Object System.Collections.Generic.List[object];foreach($s in $sr){if($idx.ContainsKey($s.fingerprint)){foreach($c in $idx[$s.fingerprint].ToArray()){$cross.Add([pscustomobject]@{fingerprint=$s.fingerprint;stadtler_filename=$s.filename;stadtler_path=$s.path;clspl_filename=$c.filename;clspl_path=$c.path;relation="EXACT_SUPPLY_CHAIN_DUPLICATE"})}}};$cross.ToArray()|Export-Csv (Join-Path $fpdir "stadtler-clspl-exact-crosswalk.csv") -NoTypeInformation -Encoding UTF8;Write-Host ("Exact Stadtler <-> CLSPL crosswalk rows: "+$cross.Count)
Step "Indexing Stadtler XML by class and seven-position code";$xidx=@{};$xinv=New-Object System.Collections.Generic.List[object];foreach($s in $exp){$files=@(Get-ChildItem -LiteralPath (Join-Path $stadt ($s.F+"\instances")) -Filter "*.xml" -File);foreach($f in $files){[xml]$d=Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8;$iid=$d.DocumentElement.GetAttribute("instanceId");$name=$d.DocumentElement.GetAttribute("name");$code=NormCode $f.Name;if([string]::IsNullOrWhiteSpace($code)){$code=NormCode $iid};if([string]::IsNullOrWhiteSpace($code)){$code=NormCode $name};$rec=[pscustomobject]@{test_set=$s.C;code=$code;filename=$f.Name;path=$f.FullName;instance_id=$iid;name=$name};$xinv.Add($rec);if(-not[string]::IsNullOrWhiteSpace($code)){$k=$s.C+"|"+$code;if(-not$xidx.ContainsKey($k)){$xidx[$k]=New-Object System.Collections.Generic.List[object]};$xidx[$k].Add($rec)}}};$xinv.ToArray()|Export-Csv (Join-Path $rep "stadtler-xml-code-inventory.csv") -NoTypeInformation -Encoding UTF8
Step "Loading and deduplicating Stadtler literature rows";$seen=@{};$refs=New-Object System.Collections.Generic.List[object];$csvs=@(Get-ChildItem -LiteralPath $lit -Filter "*-resolved-references.csv" -File -ErrorAction SilentlyContinue);foreach($csv in $csvs){foreach($r in Import-Csv $csv.FullName){$wb=$r.workbook;if([string]::IsNullOrWhiteSpace($wb)){$wb=$csv.Name};$cl=WbClass $wb;$code=NormCode $r.source_instance_id;$dk=$cl+"|"+$code+"|"+$r.objective+"|"+$r.lower_bound;if($seen.ContainsKey($dk)){continue};$seen[$dk]=$true;$refs.Add([pscustomobject]@{test_set=$cl;source_instance_id=$r.source_instance_id;code=$code;objective=$r.objective;lower_bound=$r.lower_bound;source_workbook=$wb;source_sheet=$r.sheet})}};Write-Host ("Unique literature rows after deduplication: "+$refs.Count)
Step "Mapping literature by class plus seven-position code";$mapped=New-Object System.Collections.Generic.List[object];$unmapped=New-Object System.Collections.Generic.List[object];$legacy=New-Object System.Collections.Generic.List[object];foreach($r in $refs.ToArray()){if($r.test_set-eq"LEGACY-CM"){$legacy.Add([pscustomobject]@{test_set=$r.test_set;source_instance_id=$r.source_instance_id;code=$r.code;objective=$r.objective;lower_bound=$r.lower_bound;source_workbook=$r.source_workbook;status="LEGACY_NON_OFFICIAL_ARCHIVE_REFERENCE"});continue};if($r.test_set-eq"UNKNOWN" -or [string]::IsNullOrWhiteSpace($r.code)){$unmapped.Add([pscustomobject]@{test_set=$r.test_set;source_instance_id=$r.source_instance_id;code=$r.code;objective=$r.objective;lower_bound=$r.lower_bound;source_workbook=$r.source_workbook;candidate_count=0;status="NO_CLASS_OR_CODE"});continue};$k=$r.test_set+"|"+$r.code;$cand=@();if($xidx.ContainsKey($k)){$cand=@($xidx[$k].ToArray())};if($cand.Count-eq1){$m=$cand[0];$mapped.Add([pscustomobject]@{test_set=$r.test_set;source_instance_id=$r.source_instance_id;canonical_code=$r.code;lsdm_filename=$m.filename;lsdm_path=$m.path;objective=$r.objective;lower_bound=$r.lower_bound;objective_status=$(if([string]::IsNullOrWhiteSpace($r.objective)){""}else{"LITERATURE_BEST_KNOWN"});lower_bound_status=$(if([string]::IsNullOrWhiteSpace($r.lower_bound)){""}else{"LITERATURE_LOWER_BOUND"});verified="False";source_workbook=$r.source_workbook;source_sheet=$r.source_sheet;mapping_status="UNIQUE_CLASS_PLUS_SEVEN_POSITION_CODE"})}else{$unmapped.Add([pscustomobject]@{test_set=$r.test_set;source_instance_id=$r.source_instance_id;code=$r.code;objective=$r.objective;lower_bound=$r.lower_bound;source_workbook=$r.source_workbook;candidate_count=$cand.Count;status=$(if($cand.Count-eq0){"NO_GENERATED_XML_FOR_CODE"}else{"AMBIGUOUS_CODE_WITHIN_CLASS"})})}}
$mapped.ToArray()|Sort-Object test_set,canonical_code|Export-Csv (Join-Path $meta "STADTLER-LITERATURE-REFERENCES-v0.4.1.csv") -NoTypeInformation -Encoding UTF8;$unmapped.ToArray()|Sort-Object test_set,code|Export-Csv (Join-Path $meta "STADTLER-LITERATURE-UNMAPPED-v0.4.1.csv") -NoTypeInformation -Encoding UTF8;$legacy.ToArray()|Sort-Object code|Export-Csv (Join-Path $meta "STADTLER-LEGACY-CM-REFERENCES-v0.4.1.csv") -NoTypeInformation -Encoding UTF8
Write-Host ("Mapped official literature rows: "+$mapped.Count);Write-Host ("Unmapped official literature rows: "+$unmapped.Count);Write-Host ("Legacy classcm rows: "+$legacy.Count)
Step "Generating GitHub summary";$rd=New-Object System.Collections.Generic.List[string];$rd.Add("# Stadtler 2003 MLCLSP benchmark");$rd.Add("");$rd.Add("> v0.4.1 incremental post-processing. The 2,100 XML instances generated by v0.4.0 R3 are preserved unchanged.");$rd.Add("");$rd.Add("| Test set | XML | Checker |");$rd.Add("|---|---:|---|");foreach($v in $val.ToArray()){$rd.Add("| "+$v.test_set+" | "+$v.actual+" | **VALID** |")};$rd.Add("| **Total** | **2100** | **VALID** |");$rd.Add("");$rd.Add("- Unique literature rows: **"+$refs.Count+"**");$rd.Add("- Official rows mapped: **"+$mapped.Count+"**");$rd.Add("- Official rows unresolved: **"+$unmapped.Count+"**");$rd.Add("- Legacy classcm rows: **"+$legacy.Count+"**");$rd.Add("- Exact Stadtler / CLSPL duplicate pairs: **"+$cross.Count+"**");[IO.File]::WriteAllLines((Join-Path $stadt "README.md"),$rd.ToArray(),(New-Object Text.UTF8Encoding($false)))
Step "v0.4.1 summary";Write-Host "Stadtler XML preserved and validated: 2100 / 2100";Write-Host "Checker campaigns preserved and VALID: 8 / 8";Write-Host ("Stadtler fingerprints: "+$sr.Count);Write-Host ("CLSPL canonical fingerprints: "+$cr.Count);Write-Host ("Exact Stadtler <-> CLSPL pairs: "+$cross.Count);Write-Host ("Unique literature rows: "+$refs.Count);Write-Host ("Official literature mapped: "+$mapped.Count);Write-Host ("Official literature unresolved: "+$unmapped.Count);Write-Host ("Legacy classcm rows: "+$legacy.Count);Write-Host ("Reports: "+$rep)
